// function flatten(arr) mein nested array do
// Agar array nahi: []
// Agar koi element array nahi hai: "Invalid nested array"
// Warna flat array do

solution:
function flatten(arr) {
  if (!Array.isArray(arr)) return []
  if (arr.some(item => !Array.isArray(item))) return "Invalid nested array"
  return arr.flat()
}
